INSERT INTO `categories` VALUES (4,'SẢN PHẨM','sanpham',NULL,NULL,NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-04-28 05:35:44','2021-08-04 10:52:49'),(5,'Product','product-1',NULL,NULL,NULL,NULL,0,0,'publish','en_US',NULL,NULL,'2021-04-28 05:36:27','2021-04-28 05:36:27'),(6,'DỰ ÁN','du-an',NULL,NULL,NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-04-28 05:37:00','2021-08-04 10:52:38'),(7,'project','project',NULL,NULL,NULL,NULL,0,0,'publish','en_US',NULL,NULL,'2021-04-28 05:37:29','2021-04-28 05:37:38'),(8,'DỊCH VỤ','dich-vu',NULL,'Chúng tôi cung cấp các dịch vụ về hệ thống quan trắc môi trường tự động, liên tục để hỗ trợ doanh nghiệp đo lường, theo dõi các chỉ số liên quan, để kịp thời cập nhật và xử lý khi có lỗi xảy ra',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-07-05 14:05:04','2021-08-04 10:52:29'),(10,'DỊCH VỤ LẮP ĐẶT HỆ THỐNG QUAN TRẮC TỰ ĐỘNG','he-quan-trac-nuoc',8,'MTG chuyên cung cấp các dịch vụ đa dạng về hệ thống quan trắc tự động, liên tục như: nước thải, nước ngầm, nước mặt, khí thải, khí xung quanh,....',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-04 10:56:55','2021-08-17 14:36:27'),(11,'BẢO TRÌ, BẢO DƯỠNG, THAY THẾ THIẾT BỊ','he-quan-trac-khi-tu-dong',8,'Điểm khác biệt của MTG là sự đồng bộ hệ thống, tạo điều kiện thuận lợi để tiến hành các dịch vụ hậu mãi như bảo trì, bảo dưỡng trạm quan trắc nước thải, khí thải; Thay thế thiết bị cho hệ thống quan trắc khí thải, nước thải tự động, liên tục; Thay thế datalogger, đảm bảo duy trì và đáp ứng các bộ luật, thông tư hiện hành.',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-04 10:59:10','2025-12-20 13:21:04'),(12,'DỊCH VỤ TƯ VẤN MÔI TRƯỜNG','dich-vu-moi-truong',8,'Ngoài dịch vụ lắp đặt hệ quan trắc, MTG còn cung cấp các dịch vụ liên quan đến môi trường khác như: Lập báo cáo DTM, tư vấn các điều luật, thông tư hiện hành; sữa chữa bảo trì hệ thống quan trắc; kiểm định hiệu chuẩn; hiệu chuẩn định kì; kiểm tra thiết bị quan trắc; Thay thế datalogger... và các dịch vụ liên quan khác',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-04 11:00:47','2025-12-20 14:10:26'),(13,'FPI','fpi',4,'FPI là nhà cung cấp độc quyền của MTG từ Trung Quốc. Các sản phẩm của FPI đạt các tiêu chí chuẩn về chứng chỉ TUV, EPA với mức giá cạnh tranh nhất hiện tại. \r\nFPI là thương hiệu nổi tiếng nhất tại Trung Quốc trong lĩnh vực cung cấp các thiết bị cho hệ thống quan trắc khí tự động, liên tục, cùng chất lượng và giá tốt nhất trên thị trường',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-04 11:07:27','2021-08-26 09:07:25'),(14,'MTG - HỆ THỐNG QUAN TRẮC KHÍ TỰ ĐỘNG','mtg',4,'MTG đang là OEM của Minh Thành, cũng có xuất thân từ Trung Quốc. Điểm mạnh của nhãn hàng MTG là sức trẻ, sự sáng tạo và hệ thống đồng bộ và giá cả phải chăng',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-04 11:29:29','2021-08-17 15:06:06'),(15,'BOQU - HỆ THỐNG QUAN TRẮC NƯỚC TỰ ĐỘNG','boqu',4,'BOQU là nhà cung cấp từ Thượng Hải, Trung Quốc có nhiều năm kinh nghiệm trong việc sản xuất máy phân tích nước với hơn 50 chứng chỉ kỹ thuật cho phần mềm và 23 bằng sáng chế kỹ thuật. BOQU dẫn đầu trong lĩnh vực thiết bị giám sát nước',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-04 11:31:51','2021-08-17 15:06:19'),(16,'HORIBA - HỆ THỐNG QUAN TRẮC NƯỚC TỰ ĐỘNG','horiba',4,'HORIBA là đối tác cung cấp các hệ thống phân tích và đo lường hàng đầu, có trụ sở chính tại Nhật Bản. HORIBA dẫn đầu về các kỹ thuật và công nghê đo lường để đo hệ thống khí, không khí, nước. Với MTG, HORIBA là đối tác chuyên cung cấp các thiết bị trong hệ thống quan trắc nước tự động',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-04 11:34:29','2021-08-17 15:06:34'),(17,'TIN TỨC','tin-tuc',NULL,'Các tin tức mới nhất về các thông tư, nghị định hiện hành về việc lắp đặt hệ thống quan trắc môi trường tự động, liên tục được MTG tổng hợp và tóm tắt lại cho Quý khách hàng nắm rõ',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-11 17:18:31','2021-08-11 17:18:31'),(18,'PHẦN MỀM NHẬN TRUYỀN VÀ QUẢN LÝ DỮ LIỆU','phan-mem-quan-ly-trung-tam',8,'MTG luôn nghiên cứu, tìm tòi và phát triển hệ thống phần mềm quản lý trung tâm, hỗ trợ tích hợp quản lý đa hệ quan trắc  với tính ứng dụng cao và đáp ứng chính xác yêu cầu về kỹ thuật',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-17 14:41:17','2025-12-20 13:38:25'),(19,'OEM/ODM - HỆ THỐNG PHÒNG NGHIÊN CỨU SẢN PHẨM','oemodm-he-thong-phong-nghien-cuu-san-pham',8,'Ngoài các dịch vụ về lắp đặt hệ thống quan trắc khí thải, MTG cung cấp cả dịch vụ OEM/ODM cho các doanh nghiệp, đối tác có nhu cầu sản xuất, gia công thiết bị với thương hiệu riêng, với chất lượng đạt chuẩn',NULL,NULL,0,0,'publish','vi',NULL,NULL,'2021-08-17 14:43:33','2021-11-28 14:53:46');
