INSERT INTO `content_blocks` VALUES (1,'about-us','about us','<section class=\"about-us-section section-padding\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col col-md-6\">\r\n<div class=\"section-title\"><span style=\"color:#000000;\"><span style=\"font-size:16px;\">Giới thiệu</span></span>\r\n<h1><span style=\"color:#000000;\"><span style=\"font-size:22px;\">VỀ C&Ocirc;NG TY TNHH MINH TH&Agrave;NH GROUP</span></span></h1>\r\n</div>\r\n\r\n<div class=\"details\">\r\n<p><span style=\"color:#000000;\"><span style=\"font-size:18px;\">Với đội ngũ chuy&ecirc;n gia c&oacute; kinh nghiệm được đ&agrave;o tạo b&agrave;i bản trong v&agrave; ngo&agrave;i nước, với mối quan hệ bền chặt với c&aacute;c đối t&aacute;c cung cấp thiết bị uy t&iacute;n trong nước v&agrave; quốc tế, c&ugrave;ng c&aacute;i T&acirc;m v&agrave; sự nỗ lực kh&ocirc;ng ngừng học hỏi v&agrave; cải tiến c&ocirc;ng nghệ, C&ocirc;ng ty TNHH Minh Th&agrave;nh Group đ&atilde; vinh dự trở th&agrave;nh đối t&aacute;c tư vấn, lắp đặt v&agrave; ho&agrave;n thiện hệ thống trạm quan trắc online cho rất nhiều nh&agrave; m&aacute;y như:</span></span></p>\r\n\r\n<div class=\"clearfix\">\r\n<p><span style=\"color:#000000;\"><span style=\"font-size:18px;\">&nbsp; &nbsp; &nbsp; &nbsp;C&ocirc;ng ty TNHH Seojin Vietnam&nbsp;</span></span></p>\r\n\r\n<p><span style=\"color:#000000;\"><span style=\"font-size:18px;\">&nbsp; &nbsp; &nbsp; &nbsp;C&ocirc;ng ty Cổ phần Tập đo&agrave;n Phượng Ho&agrave;ng Xanh A&amp;A</span></span></p>\r\n\r\n<p><span style=\"color:#000000;\"><span style=\"font-size:18px;\">&nbsp; &nbsp; &nbsp; &nbsp;C&ocirc;ng ty TNHH K&iacute;nh nổi Việt - Nhật</span></span></p>\r\n\r\n<p><span style=\"color:#000000;\"><span style=\"font-size:18px;\">&nbsp; &nbsp; &nbsp; &nbsp;Nh&agrave; m&aacute;y Xi măng Lưu X&aacute;</span></span></p>\r\n</div>\r\n\r\n<div class=\"btns\"><a class=\"theme-btn\" href=\"/gioi-thieu\"><span style=\"color:#000000;\">Chi Tiết</span></a></div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"col col-md-6\">\r\n<div class=\"right-col\">\r\n<div class=\"img-holder\"><img alt=\"\" src=\"/storage/uploads/kinh-noi-vfg/img-0437.jpeg\" style=\"width: 600px; height: 750px;\" /></div>\r\n\r\n<div class=\"video-holder\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<!-- end container --></section>','vi','publish','2021-04-30 03:17:43','2021-11-26 19:58:13'),(2,'map','map','<div class=\"gmap_canvas\"><iframe frameborder=\"0\" id=\"gmap_canvas\" marginheight=\"0\" marginwidth=\"0\" scrolling=\"no\" src=\"https://maps.google.com/maps?q=nh%C3%A0%20D1%20ng%C3%B5%20181%20nguy%E1%BB%85n%20l%C6%B0%C6%A1ng%20b%E1%BA%B1ng&amp;t=&amp;z=15&amp;ie=UTF8&amp;iwloc=&amp;output=embed\"></iframe></div>','vi','publish','2021-04-30 04:03:41','2021-04-30 04:03:41'),(3,'map-1','map','<div class=\"gmap_canvas\"><iframe frameborder=\"0\" id=\"gmap_canvas\" marginheight=\"0\" marginwidth=\"0\" scrolling=\"no\" src=\"https://maps.google.com/maps?q=nh%C3%A0%20D1%20ng%C3%B5%20181%20nguy%E1%BB%85n%20l%C6%B0%C6%A1ng%20b%E1%BA%B1ng&amp;t=&amp;z=15&amp;ie=UTF8&amp;iwloc=&amp;output=embed\"></iframe></div>','en_US','publish','2021-04-30 04:04:10','2021-04-30 04:04:10'),(4,'main-slide','Main Slide','<section class=\"hero-slider hero-style-1\">\r\n<div class=\"swiper-container\">\r\n<div class=\"swiper-wrapper\">\r\n<div class=\"swiper-slide\">\r\n<div class=\"slide-inner slide-bg-image\" data-background=\"/storage/uploads/main-slider/mtlg.jpg\">\r\n<div class=\"container\">\r\n<div class=\"slide-title\" data-swiper-parallax=\"300\">\r\n<h2><span style=\"font-size:22px;\">CHUY&Ecirc;N CUNG CẤP GIẢI PH&Aacute;P QUAN TRẮC M&Ocirc;I TRƯỜNG TỰ ĐỘNG</span></h2>\r\n</div>\r\n\r\n<div class=\"slide-text\" data-swiper-parallax=\"400\">\r\n<p><span style=\"font-size:18px;\">Cung cấp, lắp đặt hệ thống quan trắc kh&iacute; thải, nước thải, nước ngầm,... tự động li&ecirc;n tục. Đạt ti&ecirc;u chuẩn TUV (Đức), EPA (Hoa Kỳ). Tư vấn, thiết kế, thi c&ocirc;ng nhanh gọn, hiệu quả</span></p>\r\n</div>\r\n\r\n<div class=\"clearfix\">&nbsp;</div>\r\n\r\n<div class=\"slide-btns\" data-swiper-parallax=\"500\"><span style=\"font-size:16px;\"><a class=\"theme-btn\" href=\"/tin-tuc\">Chi tiết</a></span></div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"swiper-slide\">\r\n<div class=\"slide-inner slide-bg-image\" data-background=\"/themes/ripple/images/images_mt/slider/slide-4.jpg\">\r\n<div class=\"container\">\r\n<div class=\"slide-title\" data-swiper-parallax=\"300\">\r\n<h2><span style=\"font-size:22px;\">QUAN TRẮC KH&Iacute; THẢI TỰ ĐỘNG ONLINE</span></h2>\r\n</div>\r\n\r\n<div class=\"slide-text\" data-swiper-parallax=\"400\">\r\n<p><span style=\"font-size:18px;\">C&ocirc;ng ty TNHH Minh Th&agrave;nh Group c&ugrave;ng với đội ngũ chuy&ecirc;n gia của m&igrave;nh đ&atilde; tập trung nghi&ecirc;n cứu nhiều năm v&agrave; đưa ra được giải ph&aacute;p tối ưu, đem đến cho qu&yacute; kh&aacute;ch h&agrave;ng sự an t&acirc;m với giải ph&aacute;p Quan trắc m&ocirc;i trường&nbsp;Tự động &ndash; Li&ecirc;n tục</span></p>\r\n</div>\r\n\r\n<div class=\"clearfix\">&nbsp;</div>\r\n\r\n<div class=\"slide-btns\" data-swiper-parallax=\"500\"><span style=\"font-size:16px;\"><a class=\"theme-btn\" href=\"/he-thong-quan-trac-khi-thai-online-lien-tuc\">Chi tiết</a></span></div>\r\n</div>\r\n</div>\r\n</div>\r\n<!-- end swiper-slide -->\r\n\r\n<div class=\"swiper-slide\">\r\n<div class=\"slide-inner slide-bg-image\" data-background=\"/storage/uploads/main-slider/ncth.jpg\">\r\n<div class=\"container\">\r\n<div class=\"slide-title\" data-swiper-parallax=\"300\">\r\n<h2><span style=\"font-size:22px;\">QUAN TRẮC NƯỚC THẢI TỰ ĐỘNG ONLINE</span></h2>\r\n</div>\r\n\r\n<div class=\"slide-text\" data-swiper-parallax=\"400\">\r\n<p><span style=\"font-size:18px;\">Mỗi nh&agrave; m&aacute;y, x&iacute; nghiệp c&oacute; đặc t&iacute;nh v&agrave; lưu lượng nước thải kh&aacute;c nhau, cũng như nhu cầu v&agrave; ng&acirc;n s&aacute;ch kh&aacute;c nhau. T&ocirc;n trọng đặc t&iacute;nh ri&ecirc;ng biệt n&agrave;y, đội ngũ chuy&ecirc;n gia MTG&nbsp;sẽ tiến h&agrave;nh khảo s&aacute;t v&agrave; tư vấn bộ thiết bị ph&ugrave; hợp nhất</span></p>\r\n</div>\r\n\r\n<div class=\"clearfix\">&nbsp;</div>\r\n\r\n<div class=\"slide-btns\" data-swiper-parallax=\"500\"><span style=\"font-size:16px;\"><a class=\"theme-btn\" href=\"/he-thong-quan-trac-nuoc-thai-tu-dong-lien-tuc\">Chi tiết</a></span></div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"swiper-slide\">\r\n<div class=\"slide-inner slide-bg-image\" data-background=\"/themes/ripple/images/images_mt/slider/slide-3.jpg\">\r\n<div class=\"container\">\r\n<div class=\"slide-title\" data-swiper-parallax=\"300\">\r\n<h2><span style=\"font-size:22px;\">DỊCH VỤ KH&Aacute;C</span></h2>\r\n</div>\r\n\r\n<div class=\"slide-text\" data-swiper-parallax=\"400\">\r\n<p><span style=\"font-size:18px;\">H&atilde;y li&ecirc;n hệ ch&uacute;ng t&ocirc;i để được phục vụ tốt nhất</span></p>\r\n</div>\r\n\r\n<div class=\"clearfix\">&nbsp;</div>\r\n\r\n<div class=\"slide-btns\" data-swiper-parallax=\"500\"><span style=\"font-size:16px;\"><a class=\"theme-btn\" href=\"/dich-vu\">Xem th&ecirc;m</a></span></div>\r\n</div>\r\n</div>\r\n<!-- end slide-inner --></div>\r\n<!-- end swiper-slide --></div>\r\n<!-- end swiper-wrapper --><!-- swipper controls -->\r\n\r\n<div class=\"swiper-pagination\">&nbsp;</div>\r\n\r\n<div class=\"swiper-button-next\">&nbsp;</div>\r\n\r\n<div class=\"swiper-button-prev\">&nbsp;</div>\r\n</div>\r\n</section>','vi','publish','2021-07-07 02:22:36','2021-10-23 10:41:01'),(5,'why-choose','Why choose','<section class=\"why-choose-section section-padding\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col col-lg-6 col-lg-offset-3 col-md-8 col-md-offset-2\">\r\n<div class=\"section-title-s3\"><strong><span style=\"font-size:20px;\">Năng lực cạnh tranh</span></strong>\r\n<h2><span style=\"font-size:20px;\">Tại sao lựa chọn ch&uacute;ng t&ocirc;i!</span></h2>\r\n\r\n<p><span style=\"font-size:18px;\">Ch&uacute;ng t&ocirc;i cung cấp giải ph&aacute;p quan trắc chất lượng cao với gi&aacute; th&agrave;nh cạnh tranh nhất thị trường</span></p>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n	<div class=\"col col-xs-12\">\r\n		<div class=\"why-choose-grids clearfix\">\r\n			<div class=\"grid\">\r\n				<a href=\"#\">\r\n					<i class=\"fi flaticon-network-1\"></i>\r\n					<h3><span style=\"font-size:20px;\">Công nghệ tiên tiến, độc quyền</span></h3>\r\n				</a>\r\n				<p><span style=\"font-size:18px;\">Công nghệ UV-DOAS hiện đại, đặc biệt với các khu xử lý chất thải, rác thải, hệ thống lò hơi</span></p>\r\n			</div>\r\n\r\n			<div class=\"grid\" style=\"height:283 !important\">\r\n				<a href=\"#\">\r\n					<i class=\"fi flaticon-circular-label-with-certified-stamp\"></i>\r\n					<h3><span style=\"font-size:20px;\">Thay thế, lắp đặt thiết bị&nbsp;</span></h3>\r\n				</a>\r\n				<p><span style=\"font-size:18px;\">Lộ trình, kế hoạch thay thế rõ ràng, với các thiệt bị chính hãng, cùng chế độ hậu mãi có lợi</span></p>\r\n			</div>\r\n\r\n			<div class=\"grid\">\r\n				<a href=\"#\">\r\n					<i class=\"fi flaticon-chip\"></i>\r\n					<h3><span style=\"font-size:20px;\">Giá thành cạnh tranh nhất</span></h3>\r\n				</a>\r\n				<p><span style=\"font-size:18px;\">Chúng tôi cam kết cung cấp sản phẩm cao cấp, với mức giá trung cấp, cạnh tranh nhất thị trường</span></p>\r\n			</div>\r\n\r\n			<div class=\"grid\" style=\"word-spacing: -2px;\">\r\n				<a href=\"#\">\r\n					<i class=\"fi flaticon-24-hours\"></i>\r\n					<h3><span style=\"font-size:20px;\">Phần mềm quản lý trung tâm</span></h3>\r\n				</a>	\r\n				<p><span style=\"font-size:18px;\">Hệ thống phần mềm quản lý trung tâm tích hợp dữ liệu nhanh, chính xác, hiệu quả với độ bảo mật tuyệt đối</span></p>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n</div>\r\n</section>','vi','publish','2021-07-07 02:23:09','2021-11-27 02:32:03'),(6,'services','Services','<section class=\"service-section section-padding\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col col-md-6\">\r\n<div class=\"section-title-s2\"><span>Giải ph&aacute;p của ch&uacute;ng t&ocirc;i</span>\r\n<h2>Cung cấp hệ thống quan trắc h&agrave;ng đầu Việt Nam</h2>\r\n</div>\r\n</div>\r\n\r\n<div class=\"col col-md-6\">\r\n<div class=\"title-text\">\r\n<p>Bằng việc ứng dụng khoa học c&ocirc;ng nghệ trong thiết kế v&agrave; quản l&yacute; vận h&agrave;nh. Bạn ho&agrave;n to&agrave;n c&oacute; thể Gi&aacute;m s&aacute;t trực tuyến th&ocirc;ng số đồng hồ, t&iacute;n hiệu v&agrave; trạng th&aacute;i hoạt động một c&aacute;ch nhanh ch&oacute;ng đồng thời c&oacute; thể gi&aacute;m s&aacute;t v&agrave; cảnh b&aacute;o c&aacute;c sự cố xảy ra. Ngo&agrave;i ra ch&uacute;ng t&ocirc;i c&ograve;n cung cấp th&ecirc;m rất nhiều t&ugrave;y chọn kh&aacute;c như:&rdquo; Điều khiển m&aacute;y m&oacute;c, Lập b&aacute;o c&aacute;o, v&agrave; gửi cảnh b&aacute;o tự động th&ocirc;ng qua SMS v&agrave; email</p>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n    <div class=\"col col-xs-12\">\r\n        <div class=\"service-grids clearfix\">\r\n            <div class=\"grid\">\r\n                <i class=\"fi flaticon-gear\"></i>\r\n                <h4><a href=\"#\">Sửa chữa, thay thế thiết bị</a></h4>\r\n                <p>Giám sát trực tuyến thông số đồng hồ, tín hiệu.</p>\r\n                <a href=\"#\" class=\"read-more\">Xem thêm&nbsp;<i class=\"fi flaticon-next\"></i></a>\r\n            </div>\r\n            <div class=\"grid\">\r\n                <i class=\"fi flaticon-worker\"></i>\r\n                <h4><a href=\"#\">Tư vấn cung cấp thiết bị và giải pháp</a></h4>\r\n                <p>Tư vấn, cung cấp thiết bị và giải pháp lắp đặt trạm quan trắc khí thải, nước thải và cá công trình tự động khác.</p>\r\n                <a href=\"#\" class=\"read-more\">Xem thêm&nbsp;<i class=\"fi flaticon-next\"></i></a>\r\n            </div>\r\n            <div class=\"grid\">\r\n                <i class=\"fi flaticon-time-management\"></i>\r\n                <h4><a href=\"#\">Dịch vụ môi trường</a></h4>\r\n                <p>Tư vấn và cung cấp các giải pháp xử lý nước thải.</p>\r\n                <a href=\"#\" class=\"read-more\">Xem thêm&nbsp;<i class=\"fi flaticon-next\"></i></a>\r\n            </div>\r\n            <div class=\"grid\">\r\n                <i class=\"fi flaticon-helmet\"></i>\r\n                <h4><a href=\"#\">Lập báo cáo</a></h4>\r\n                <p>Lập báo cáo DTM, báo cáo tác động môi trường theo luật môi trường hiện hành. </p>\r\n                <a href=\"#\" class=\"read-more\">Xem thêm&nbsp;<i class=\"fi flaticon-next\"></i></a>\r\n            </div>\r\n        </div>\r\n        <div class=\"view-all\">\r\n            <p>Xem<a href=\"#\">&nbsp;toàn bộ&nbsp;</a> giải pháp thông minh</p>\r\n        </div>\r\n    </div>\r\n</div>\r\n</div>\r\n</section>','vi','publish','2021-07-07 02:23:24','2021-11-27 02:22:15'),(7,'featured-project','Featured Project','<section class=\"featured-project-section section-padding\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col col-lg-6 col-lg-offset-3 col-md-8 col-md-offset-2\">\r\n<div class=\"section-title-s5\">\r\n<p><strong><font color=\"#000000\"><span style=\"font-size: 20px;\">Dự &aacute;n ti&ecirc;u biểu</span></font></strong></p>\r\n\r\n<h2><span style=\"color:#000000;\"><strong><span style=\"font-size:22px;\">Những dự &aacute;n m&agrave; ch&uacute;ng t&ocirc;i đ&atilde; ho&agrave;n th&agrave;nh</span></strong></span></h2>\r\n\r\n<p style=\"text-align: justify;\"><span style=\"color:#000000;\"><span style=\"font-size:18px;\">Với đội ngũ chuy&ecirc;n gia c&oacute; kinh nghiệm được đ&agrave;o tạo b&agrave;i bản trong v&agrave; ngo&agrave;i nước, với mối quan hệ bền chặt với c&aacute;c đối t&aacute;c cung cấp thiết bị uy t&iacute;n trong nước v&agrave; quốc tế, c&ugrave;ng c&aacute;i T&acirc;m v&agrave; sự nỗ lực kh&ocirc;ng ngừng học hỏi v&agrave; cải tiến c&ocirc;ng nghệ, C&ocirc;ng ty TNHH Minh Th&agrave;nh Group đ&atilde; vinh dự trở th&agrave;nh đối t&aacute;c tư vấn, lắp đặt v&agrave; ho&agrave;n thiện hệ thống trạm quan trắc online cho rất nhiều nh&agrave; m&aacute;y như:</span></span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"content-area\">\r\n<div class=\"project-grids clearfix\">\r\n<div class=\"grid\">\r\n<div class=\"overlay\">\r\n<p style=\"text-align: justify;\"><span style=\"color:#000000;\"><span style=\"font-size:18px;\"><span class=\"count\">01.</span></span></span></p>\r\n\r\n<h3 style=\"text-align: justify;\"><span style=\"color:#000000;\"><span style=\"font-size:18px;\">C&Ocirc;NG TY TNHH XUẤT NHẬP KHẨU V&Agrave; SẢN XUẤT SEIDO</span></span></h3>\r\n\r\n<p><span style=\"font-size:18px;\">&nbsp;Ng&agrave;nh nhựa&nbsp;l&agrave; một trong những lĩnh vực bắt buộc phải lắp đặt Hệ thống Quan trắc kh&iacute; thải tự động theo Nghị định 40/2019/NĐ-CP.&nbsp;Năm 2021, C&ocirc;ng ty TNHH Xuất nhập khẩu v&agrave; Sản xuất Seido&nbsp;đ&atilde; quyết định đầu tư hạng mục Thiết bị Quan trắc kh&iacute; thải tự động với 8 th&ocirc;ng số cho nh&agrave; m&aacute;y sản xuất nhựa&nbsp;tại Quảng Ninh. MTG&nbsp;đ&atilde; được lựa chọn l&agrave; nh&agrave; thầu thực hiện hạng mục n&agrave;y.</span></p>\r\n\r\n<p style=\"text-align: justify;\"><span style=\"font-size:18px;\"><a class=\"theme-btn\" href=\"/cong-ty-tnhh-seido#\"><span style=\"color:#000000;\">Xem th&ecirc;m</span></a></span></p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"grid\">\r\n<div class=\"overlay\">\r\n<p style=\"text-align: justify;\"><span style=\"color:#000000;\"><span style=\"font-size:18px;\"><span class=\"count\">02.</span></span></span></p>\r\n\r\n<h3 style=\"text-align: justify;\"><font color=\"#000000\"><span style=\"font-size: 18px;\">C&Ocirc;NG TY TNHH SEOJIN VIỆT NAM</span></font></h3>\r\n\r\n<p style=\"text-align: justify;\"><span style=\"font-size:18px;\">Tập đo&agrave;n Seojin c&oacute; mặt tại Việt Nam từ năm 2011 l&agrave; C&ocirc;ng ty c&oacute; 100% vốn đầu tư của quốc gia H&agrave;n Quốc. Đến nay, Seojin đ&atilde; kh&ocirc;ng ngừng mở rộng quy m&ocirc; v&agrave; ph&aacute;t triển mạnh mẽ trong lĩnh vực sản xuất về thiết bị thu ph&aacute;t s&oacute;ng trong, ngo&agrave;i nước v&agrave; vỏ điện thoại, linh kiện điện tử cho tập đo&agrave;n Samsung ở Việt Nam.</span></p>\r\n\r\n<p style=\"text-align: justify;\"><span style=\"font-size:18px;\"><a class=\"theme-btn\" href=\"/cong-ty-tnhh-seojin-viet-nam#\"><span style=\"color:#000000;\">Xem th&ecirc;m</span></a></span></p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"grid\">\r\n<div class=\"overlay\">\r\n<p style=\"text-align: justify;\"><span style=\"color:#000000;\"><span style=\"font-size:18px;\"><span class=\"count\">03.</span></span></span></p>\r\n\r\n<h3 style=\"text-align: justify;\"><font color=\"#000000\"><span style=\"font-size: 18px;\">C&Ocirc;NG TY TNHH MTV KH&Aacute;NH QUỲNH LONG AN</span></font></h3>\r\n\r\n<p><span style=\"font-size:18px;\">C&ocirc;ng ty TNHH Một th&agrave;nh vi&ecirc;n Kh&aacute;nh Quỳnh Long An&nbsp;được đầu tư với diện t&iacute;ch Nh&agrave; m&aacute;y khoảng&nbsp;16.965,4 m<sup>2</sup>&nbsp;v&agrave; chuy&ecirc;n sản xuất&nbsp;c&aacute;c sản phẩm từ nhựa&nbsp; với quy m&ocirc; c&ocirc;ng suất đạt 40.000 tấn sản phẩm /năm. Hệ quan trắc 8 th&ocirc;ng số cơ bản gồm:&nbsp;Lưu lượng, nhiệt độ, &aacute;p suất, bụi tổng, SO<sub>2</sub>, NO<sub>x</sub>, CO, O<sub>2</sub>&nbsp;dư.</span></p>\r\n\r\n<p style=\"text-align: justify;\"><span style=\"font-size:18px;\"><a class=\"theme-btn\" href=\"/cong-ty-tnhh-khanh-quynh-long-an#\"><span style=\"color:#000000;\">Xem th&ecirc;m</span></a></span></p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"grid\">\r\n<div class=\"overlay\">\r\n<p style=\"text-align: justify;\"><span style=\"color:#000000;\"><span style=\"font-size:18px;\"><span class=\"count\">04.</span></span></span></p>\r\n\r\n<h3 style=\"text-align: justify;\"><span style=\"font-size:18px;\">C&Ocirc;NG TY CP NH&Ocirc;M VIỆT PH&Aacute;P - NH&Agrave; M&Aacute;Y NH&Ocirc;M VIỆT PH&Aacute;P</span></h3>\r\n\r\n<p style=\"text-align: justify;\"><span style=\"font-size:18px;\">C&ocirc;ng ty CP nh&ocirc;m Việt Ph&aacute;p - Nh&agrave; m&aacute;y nh&ocirc;m Việt Ph&aacute;p c&oacute; trụ sở ch&iacute;nh ở địa chỉ L&ocirc; A2, CN8, Khu c&ocirc;ng nghiệp Từ Li&ecirc;m H&agrave; Nội.&nbsp;</span></p>\r\n\r\n<p style=\"text-align: justify;\"><span style=\"font-size:18px;\">Trong suốt hơn&nbsp;15 năm hoạt động vừa qua,<strong>&nbsp;</strong>Nh&agrave; m&aacute;y<strong>&nbsp;</strong>nh&ocirc;m Việt Ph&aacute;p&nbsp;đ&atilde; tạo dựng được cho m&igrave;nh một thương hiệu c&oacute; uy t&iacute;n tại thị trường Việt Nam v&agrave; một số nước Ch&acirc;u &Aacute;.</span></p>\r\n\r\n<p style=\"text-align: justify;\"><span style=\"font-size:18px;\"><a class=\"theme-btn\" href=\"/cong-ty-tnhh-khoa-hoc-ky-thuat-nang-luong-mat-troi-boviet#\"><span style=\"color:#000000;\">Xem th&ecirc;m</span></a></span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section>','vi','publish','2021-07-07 02:23:51','2021-11-26 19:44:37'),(8,'partners','Partners','<section class=\"partners-section\">\r\n<h2 style=\"text-align: center; font-size: 2.375rem;\">Đối t&aacute;c chiến lược</h2>\r\n\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col col-xs-12\">\r\n<div class=\"partner-grids partners-slider\">\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/siemens-ifl-logo.png\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/kelisaike.jpg\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/humass.png\" style=\"margin-top: 20px;\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/horiba.jpg\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/FPI.jpg\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/ecd.png\" style=\"height: 100px;\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/BOQU-rs.png\" /></div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section>','vi','publish','2021-07-07 02:24:18','2021-11-26 23:11:45'),(9,'main-slide-1','Main slide','<section class=\"about-us-section section-padding\">\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col col-md-6\">\r\n<div class=\"section-title\"><span>Giới thiệu</span>\r\n<h2>C&Ocirc;NG TY TNHH MINH TH&Agrave;NH GROUP</h2>\r\n</div>\r\n\r\n<div class=\"details\">\r\n<p>Với đội ngũ chuy&ecirc;n gia c&oacute; kinh nghiệm được đ&agrave;o tạo b&agrave;i bản trong v&agrave; ngo&agrave;i nước, với mối quan hệ bền chặt với c&aacute;c đối t&aacute;c cung cấp thiết bị uy t&iacute;n trong nước v&agrave; quốc tế, c&ugrave;ng c&aacute;i T&acirc;m v&agrave; sự nỗ lực kh&ocirc;ng ngừng học hỏi v&agrave; cải tiến c&ocirc;ng nghệ, C&ocirc;ng ty TNHH Minh Th&agrave;nh Group đ&atilde; vinh dự trở th&agrave;nh đối t&aacute;c tư vấn, lắp đặt v&agrave; ho&agrave;n thiện hệ thống trạm quan trắc online cho rất nhiều nh&agrave; m&aacute;y như:</p>\r\n\r\n<div class=\"clearfix\">\r\n<ul>\r\n	<li>C&ocirc;ng ty TNHH Vinatic</li>\r\n	<li>C&ocirc;ng ty TNHH MTV Vinapaper</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>C&ocirc;ng ty TNHH K&iacute;nh nổi Việt - Nhật</li>\r\n	<li>Nh&agrave; m&aacute;y xi măng Lưu X&aacute;</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"btns\"><a class=\"theme-btn\" href=\"#\">Dịch vụ</a> <a class=\"theme-btn-s3\" href=\"#\">Li&ecirc;n hệ ngay</a></div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"col col-md-6\">\r\n<div class=\"right-col\">\r\n<div class=\"img-holder\"><img alt=\"\" src=\"https://mtgroup.tech/themes/ripple/images/images_mt/about.png\" /></div>\r\n\r\n<div class=\"video-holder\"><a class=\"hero-video-btn video-btn\" data-type=\"iframe\" href=\"https://www.youtube.com/embed/p-J7Qk6_wzg?autoplay=1\" tabindex=\"0\">Xem video giới thiệu</a></div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<!-- end container --></section>','en_US','publish','2021-07-09 12:42:41','2021-07-09 12:45:28'),(10,'why-choose-1','Why choose','<section class=\"why-choose-section section-padding\">\r\n            <div class=\"container\">\r\n                <div class=\"row\">\r\n                    <div class=\"col col-lg-6 col-lg-offset-3 col-md-8 col-md-offset-2\">\r\n                        <div class=\"section-title-s3\">\r\n                            <span>Năng lực cạnh tranh</span>\r\n                            <h2>Tại sao lựa chọn chúng tôi!</h2>\r\n                            <p>Chúng tôi có những chuuyên gia hàng đầu với giải pháp công nghệ 4.0</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row\">\r\n                    <div class=\"col col-xs-12\">\r\n                        <div class=\"why-choose-grids clearfix\">\r\n                            <div class=\"grid\">\r\n                                <i class=\"fi flaticon-network-1\"></i>\r\n                                <h3>Thay thế, lắp đặt thiết bị linh hoạt</h3>\r\n                                <p>Luôn lấy khách hàng làm trung tâm, hỗ trợ khách hàng là niềm vui của chúng tôi</p>\r\n                            </div>\r\n                            <div class=\"grid\" style=\'height:283 !important\'>\r\n                                <i class=\"fi flaticon-circular-label-with-certified-stamp\"></i>\r\n                                <h3>Chuyên gia hàng đầu, chuyên nghiệp</h3>\r\n                                <p>Chúng tôi cố nhiều chuyên gia giàu kinh nghiệm đã từng nghiên cứu ở nhiều quốc gia trên thế giới</p>\r\n                            </div>\r\n                            <div class=\"grid\">\r\n                                <i class=\"fi flaticon-chip\"></i>\r\n                                <h3>Công nghệ tiên tiến, độc quyền</h3>\r\n                                <p>Chúng tôi luôn cập nhật những giải pháp tiên tiến và hiệu quả nhất                     </p>\r\n                            </div>\r\n                            <div class=\"grid\" style=\"height: 283px;\">\r\n                                <i class=\"fi flaticon-24-hours\"></i>\r\n                                <h3>Hỗ trợ 24/7 </h3>\r\n                                <p>Luôn giải đáp thắc mắc bất cứ lúc nào khách hàng cần bất kể ngày nghỉ                     </p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div> <!-- end container -->\r\n        </section>','en_US','publish','2021-07-09 13:05:23','2021-07-09 13:05:23'),(11,'service','Service','<section class=\"service-section section-padding\">\r\n            <div class=\"container\">\r\n                <div class=\"row\">\r\n                    <div class=\"col col-md-6\">\r\n                        <div class=\"section-title-s2\">\r\n                            <span>Giải pháp của chúng tôi</span>\r\n                            <h2>Cung cấp hệ thống quan trắc hàng đầu Việt Nam</h2>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col col-md-6\">\r\n                        <div class=\"title-text\">\r\n                            <p>Bằng việc ứng dụng khoa học công nghệ trong thiết kế và quản lý vận hành. Bạn hoàn toàn có thể Giám sát trực tuyến thông số đồng hồ, tín hiệu và trạng thái hoạt động một cách nhanh chóng đồng thời có thể giám sát và cảnh báo các sự cố xảy ra. Ngoài ra chúng tôi còn cung cấp thêm rất nhiều tùy chọn khác như:” Điều khiển máy móc, Lập báo cáo, và gửi cảnh báo tự động thông qua SMS và email </p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row\">\r\n                    <div class=\"col col-xs-12\">\r\n                        <div class=\"service-grids clearfix\">\r\n                            <div class=\"grid\">\r\n                                <i class=\"fi flaticon-gear\"></i>\r\n                                <h4><a href=\"#\">Sửa chữa, thay thế thiết bị</a></h4>\r\n                                <p>  Online monitoring of clock parameters, signals</p>\r\n                                <a href=\"#\" class=\"read-more\">See more&nbsp;<i class=\"fi flaticon-next\"></i></a>\r\n                            </div>\r\n                            <div class=\"grid\">\r\n                                <i class=\"fi flaticon-worker\"></i>\r\n                                <h4><a href=\"#\">Tư vấn, cung cấp thiết bị và giải pháp</a></h4>\r\n                                <p>Provide equipment and solutions to install waste gas monitoring stations, wastewater and other automatic monitoring works</p>\r\n                                <a href=\"#\" class=\"read-more\">See more&nbsp;<i class=\"fi flaticon-next\"></i></a>\r\n                            </div>\r\n                            <div class=\"grid\">\r\n                                <i class=\"fi flaticon-time-management\"></i>\r\n                                <h4><a href=\"#\">Dịch vụ môi trường</a></h4>\r\n                                <p>Consulting and providing wastewater treatment solutions</p>\r\n                                <a href=\"#\" class=\"read-more\">See more&nbsp;<i class=\"fi flaticon-next\"></i></a>\r\n                            </div>\r\n                            <div class=\"grid\">\r\n                                <i class=\"fi flaticon-helmet\"></i>\r\n                                <h4><a href=\"#\">Prepare reports</a></h4>\r\n                                <p> Prepare DTM reports, environmental impact reports in accordance with the current Environmental Law.</p>\r\n                                <a href=\"#\" class=\"read-more\">See more&nbsp;<i class=\"fi flaticon-next\"></i></a>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"view-all\">\r\n                            <p>See <a href=\"#\">All</a> Smart solution</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div> <!-- end container -->\r\n        </section>','en_US','publish','2021-07-09 13:14:10','2021-07-10 23:26:49'),(12,'featured-project-1','Featured project','<section class=\"featured-project-section section-padding\">\r\n            <div class=\"container\">\r\n                <div class=\"row\">\r\n                    <div class=\"col col-lg-6 col-lg-offset-3 col-md-8 col-md-offset-2\">\r\n                        <div class=\"section-title-s5\">\r\n                            <span>Dự án tiêu biểu</span>\r\n                            <h2>Những dự án mà chúng tôi đã hoàn thành</h2>\r\n                            <p>Với đội ngũ chuyên gia có kinh nghiệm được đào tạo bài bản trong và ngoài nước,  với mối quan hệ bền chặt với các đối tác cung cấp thiết bị uy tín trong nước và quốc tế, cùng cái Tâm và sự nỗ lực không ngừng học hỏi và cải tiến công nghệ, Công ty TNHH Minh Thành Group đã vinh dự trở thành đối tác tư vấn, lắp đặt và hoàn thiện hệ thống trạm quan trắc online cho rất nhiều nhà máy như:</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div class=\"content-area\">\r\n                <div class=\"project-grids clearfix\">\r\n                    <div class=\"grid\" >\r\n                        <div class=\"overlay\">\r\n                            <span class=\"count\">01.</span>\r\n                            <h3>CÔNG TY CỔ PHẦN TẬP ĐOÀN PHƯỢNG HOÀNG XANH A&A</h3>\r\n                            <p>Công ty Cổ phần Tập đoàn Phượng Hoàng Xanh A&A nằm trong top đầu trên thế giới về sản xuất và cung cấp đá thạch anh với sản phẩm đá thạch anh thương hiệu VICOSTONE Quartz Surfaces. </p>\r\n                            <a href=\"#\" class=\"theme-btn\">Xem thêm</a>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"grid\">\r\n                        <div class=\"overlay\">\r\n                            <span class=\"count\">02.</span>\r\n                            <h3>PNHÀ MÁY THÉP TUYÊN QUANG</h3>\r\n                            <p>Có trụ sở chính được đặ tại: KCN thành phố Tuyên Quang, Tỉnh Tuyên Quang. Nhà máy có 3 ống khói: lò thiêu kết, lò luyện gang, lò thổi</p>\r\n                            <a href=\"#\" class=\"theme-btn\">Xem thêm</a>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"grid\">\r\n                        <div class=\"overlay\">\r\n                            <span class=\"count\">03.</span>\r\n                            <h3>NHÀ MÁY XI MĂNG BẮC GIANG</h3>\r\n                            <p>Nhà máy xi măng Bắc Giang là doanh nghiệp sản xuất xi măng P300, P200, cung cấp Clinker cho 1 số nhà máy xi măng khác.</p>\r\n                            <a href=\"#\" class=\"theme-btn\">Xem thêm</a>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"grid\">\r\n                        <div class=\"overlay\">\r\n                            <span class=\"count\">04.</span>\r\n                            <h3>CÔNG TY TNHH KHOA HỌC KỸ THUẬT NĂNG LƯỢNG MẶT TRỜI BOVIET</h3>\r\n                            <p>Công ty TNHH BoViet chuyên sản xuất tấm pin năng lượng mặt trời. Có trụ sở chính được đặt tại: KCN Song Khê - Nội Hoàng - Tỉnh Bắc Giang.</p>\r\n                            <a href=\"#\" class=\"theme-btn\">Xem thêm</a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section>','en_US','publish','2021-07-09 13:20:00','2021-07-09 13:20:00'),(13,'partner','Partner','<section class=\"partners-section\">\r\n<h2 style=\"text-align: center; font-size: 2.375rem;\">Our Partners</h2>\r\n\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col col-xs-12\">\r\n<div class=\"partner-grids partners-slider\">\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/siemens-ifl-logo.png\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/kelisaike.jpg\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/humass.png\" style=\"margin-top: 20px;\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/horiba.jpg\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/FPI.jpg\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/ecd.png\" style=\"height: 100px;\" /></div>\r\n\r\n<div class=\"grid\"><img alt=\"\" src=\"/themes/ripple/images/images_mt/partners/BOQU-rs.png\" /></div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>','en_US','publish','2021-07-09 13:22:22','2021-07-10 23:24:16');
