INSERT INTO `pages` VALUES (2,'page 1','page-1',NULL,'<p>test page 1</p>','default','/storage/uploads/1-9.jpg',1,'[{\"img\": \"/storage/uploads/1-9.jpg\", \"description\": null}]','publish','vi',NULL,NULL,'2021-04-28 06:03:19','2021-04-28 06:03:19'),(3,'Giới thiệu','gioi-thieu','introduce','<h1><strong><span style=\"color:#000000;\">CH&Agrave;O MỪNG ĐẾN VỚI&nbsp;</span></strong> <span style=\"color:#003300;\"><strong>MINH TH&Agrave;NH</strong></span><span style=\"color:#000000;\"><strong> </strong></span><span style=\"color:#009933;\"><strong>GROUP</strong></span></h1>\r\n\r\n<p>____________________</p>\r\n\r\n<p><span style=\"color:#000000;\"><meta charset=\"utf-8\" /></span></p>\r\n\r\n<p dir=\"ltr\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"color:#000000;\"><b id=\"docs-internal-guid-50dc32ac-7fff-206c-1f89-6878c65c16be\">C&ocirc;ng ty TNHH Minh Thành Group được thành l&acirc;̣p từ năm 2018 c&oacute; trụ sở tại Bắc Ninh, với lực lượng lao đ&ocirc;̣ng được đào tạo bài bản ở trong và ngoài nước. Chúng t&ocirc;i đang trở thành m&ocirc;̣t trong những c&ocirc;ng ty d&acirc;̃n đ&acirc;̀u v&ecirc;̀ lĩnh vực cung c&acirc;́p lắp đặt thi&ecirc;́t bị quan trắc khí thải và nước thải cho nhà máy, khu c&ocirc;ng nghi&ecirc;̣p</b></span></span></span></p>\r\n\r\n<p dir=\"ltr\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:16px;\">&nbsp;Từ năm 2021 đến năm 2023, Minh Th&agrave;nh Group th&agrave;nh lập&nbsp;c&aacute;c văn ph&ograve;ng đại diện v&agrave; chi nh&aacute;nh ở H&agrave; Nội, HCM, Miền Trung.</span></span></p>\r\n\r\n<p dir=\"ltr\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:16px;\">Minh Th&agrave;nh Group tập trung v&agrave;o cung cấp giải ph&aacute;p đến Kh&aacute;ch h&agrave;ng như cung cấp, lắp đặt hệ thống quan trắc kh&iacute; thải, nước thải; Gi&aacute;m s&aacute;t hoạt động khai th&aacute;c, sử dụng t&agrave;i nguy&ecirc;n nước; Tư vấn/b&aacute;o c&aacute;o M&ocirc;i trường: ĐTM, GPMT, ESG, B&aacute;o c&aacute;o Kiểm k&ecirc; ph&aacute;t thải kh&iacute; nh&agrave; k&iacute;nh, Xử l&yacute; chất thải; Vận h&agrave;nh thử nghiệm.</span></span></p>\r\n\r\n<h1><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:24px;\"><strong>1. LỊCH SỬ H&Igrave;NH TH&Agrave;NH V&Agrave; PH&Aacute;T TRIỂN</strong></span></span></h1>\r\n\r\n<p><img alt=\"\" src=\"data:image/png;base64,\" /></p>\r\n\r\n<h1><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:24px;\"><strong>2. ĐỘI NGŨ CHUY&Ecirc;N GIA NĂNG LỰC</strong></span></span></h1>\r\n\r\n<p><img alt=\"\" src=\"data:image/png;base64,\" /></p>\r\n\r\n<h1><span style=\"font-size:24px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><strong>3. TẦM NH&Igrave;N - SỨ MỆNH - GI&Aacute; TRỊ CỐT L&Otilde;I</strong></span></span></h1>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\"><meta charset=\"utf-8\" /></span></span></span></p>\r\n\r\n<ul>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<h2 dir=\"ltr\" role=\"presentation\"><span style=\"font-size:16px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"color:#000000;\"><b id=\"docs-internal-guid-ec5c6a77-7fff-a4b4-39c0-24882ee4febe\">T&acirc;̀m nhìn</b></span></span></span></h2>\r\n\r\n	<ul>\r\n		<li aria-level=\"2\" dir=\"ltr\">\r\n		<p dir=\"ltr\" role=\"presentation\"><span style=\"font-size:14px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\">Đơn vị cung cấp giải ph&aacute;p to&agrave;n diện trong lĩnh vực m&ocirc;i trường v&igrave; Quyền lợi của Kh&aacute;ch h&agrave;ng</span></span></p>\r\n		</li>\r\n		<li aria-level=\"2\" dir=\"ltr\">\r\n		<p dir=\"ltr\" role=\"presentation\"><span style=\"font-size:14px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\">Ch&uacute;ng t&ocirc;i kh&ocirc;ng ngừng đổi mới c&ocirc;ng nghệ, mở rộng dấu ấn thương hiệu trong nước v&agrave; quốc tế</span></span></p>\r\n		</li>\r\n		<li aria-level=\"2\" dir=\"ltr\">\r\n		<p dir=\"ltr\" role=\"presentation\"><span style=\"font-size:14px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\">Đồng h&agrave;nh c&ugrave;ng cộng đồng kiến tạo tương lai xanh, ph&aacute;t triển bền vững</span></span></p>\r\n		</li>\r\n	</ul>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<h2 dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\"><b id=\"docs-internal-guid-ec5c6a77-7fff-a4b4-39c0-24882ee4febe\">S</b><strong>ứ m&ecirc;̣nh</strong></span></span></span></h2>\r\n\r\n	<ul>\r\n		<li aria-level=\"2\" dir=\"ltr\">\r\n		<p dir=\"ltr\" role=\"presentation\"><span style=\"font-size:14px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><b><i><span style=\"line-height:107%\">Đối với Kh&aacute;ch h&agrave;ng:</span></i></b><span style=\"line-height:107%\">&nbsp; cung cấp giải ph&aacute;p to&agrave;n diện theo nhu cầu của Kh&aacute;ch h&agrave;ng, đảm bảo đ&aacute;p ứng quy định của nh&agrave; nước hiện h&agrave;nh, bảo vệ quyền v&agrave; lợi &iacute;ch của Kh&aacute;ch h&agrave;ng.</span></span></span></p>\r\n		</li>\r\n		<li aria-level=\"2\" dir=\"ltr\">\r\n		<p dir=\"ltr\" role=\"presentation\"><span style=\"font-size:14px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><b><i>Đối với NLĐ:</i></b> x&acirc;y dựng m&ocirc;i trường việc năng động, s&aacute;ng tạo, cơ hội ph&aacute;t triển v&agrave; đảm bảo quyền lợi của người lao động.</span></span></p>\r\n		</li>\r\n		<li aria-level=\"2\" dir=\"ltr\">\r\n		<p dir=\"ltr\" role=\"presentation\"><span style=\"font-size:14px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><b><i><span style=\"line-height:107%\">Đối với đối t&aacute;c:</span></i></b><span style=\"line-height:107%\"> tin cậy, đồng h&agrave;nh x&acirc;y dựng uy t&iacute;n, hợp t&aacute;c c&ugrave;ng ph&aacute;t triển tr&ecirc;n thị trường.</span></span></span></p>\r\n		</li>\r\n		<li aria-level=\"2\" dir=\"ltr\">\r\n		<p dir=\"ltr\" role=\"presentation\"><span style=\"font-size:14px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><b><i><span style=\"line-height:107%\">Đối với x&atilde; hội:</span></i></b><span style=\"line-height:107%\"> Đ&agrave;o tạo thế hệ trẻ tăng cường nhận thức về tầm quan trọng của bảo vệ m&ocirc;i trường th&ocirc;ng qua c&aacute;c chương tr&igrave;nh gi&aacute;o dục v&agrave; hoạt động truyền th&ocirc;ng. Đ&oacute;ng g&oacute;p t&iacute;ch cực v&agrave;o c&aacute;c hoạt động hướng về cộng đồng thể hiện tinh thần tr&aacute;ch nhiệm của c&aacute; nh&acirc;n v&agrave; doanh nghiệp.</span></span></span></p>\r\n		</li>\r\n	</ul>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<h2 dir=\"ltr\" role=\"presentation\"><span style=\"font-size:16px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"color:#000000;\"><b id=\"docs-internal-guid-ec5c6a77-7fff-a4b4-39c0-24882ee4febe\">G</b><strong>iá trị c&ocirc;́t lõi:&nbsp;</strong></span></span></span><b>:</b><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"> Ch&uacute;ng t&ocirc;i x&acirc;y dựng mọi hoạt động kinh doanh v&agrave; văn h&oacute;a doanh nghiệp dựa tr&ecirc;n ba gi&aacute; trị cốt l&otilde;i &ldquo;T&acirc;m - T&iacute;n &ndash; Tầm&rdquo;. Đ&acirc;y l&agrave; kim chỉ nam định hướng h&agrave;nh động, l&agrave; lời cam kết của ch&uacute;ng t&ocirc;i với kh&aacute;ch h&agrave;ng, đối t&aacute;c v&agrave; cộng đồng..</span></span></h2>\r\n\r\n	<ul>\r\n		<li aria-level=\"2\" dir=\"ltr\">\r\n		<p><span style=\"font-size:14px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><b><i><span style=\"line-height:107%\">T&acirc;m: </span></i></b><span style=\"line-height:107%\">nền tảng tạo ra gi&aacute; trị bền vững v&agrave; lan tỏa niềm tin, đạo đức, l&agrave;m việc tận tụy, kh&aacute;ch h&agrave;ng l&agrave; trung t&acirc;m. </span></span></span></p>\r\n		</li>\r\n		<li aria-level=\"2\" dir=\"ltr\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><b style=\"font-size: 14px;\"><i><span style=\"line-height:107%\">T&iacute;n</span></i></b><span style=\"font-size: 14px; line-height: 107%;\">: x&acirc;y dựng v&agrave; bảo vệ uy t&iacute;n doanh nghiệp, Lời cam kết với Kh&aacute;ch h&agrave;ng về năng lực thực thi, đảm bảo tiến độ thực hiện, sản phẩm chất lượng, lời hứa với Đối t&aacute;c v&agrave; tr&aacute;ch nhiệm với Đội ngũ.</span></span></li>\r\n		<li aria-level=\"2\" dir=\"ltr\">\r\n		<p><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><b><i><span style=\"line-height:107%\">Tầm: </span></i></b><span style=\"line-height:107%\">mục ti&ecirc;u v&agrave; tư duy chiến lược về sản phẩm/dịch vụ/quản trị, hướng đến tương lai, kh&aacute;t vọng vươn l&ecirc;n, năng lực đổi mới, v&agrave; khả năng th&iacute;ch nghi trong thời đại chuyển đổi. Ch&uacute;ng t&ocirc;i x&acirc;y dựng tầm nh&igrave;n d&agrave;i hạn v&agrave; h&agrave;nh động với chiến lược r&otilde; r&agrave;ng để kh&ocirc;ng ngừng ph&aacute;t triển v&agrave; dẫn đầu.</span><br />\r\n		<br />\r\n		<b id=\"docs-internal-guid-ec5c6a77-7fff-a4b4-39c0-24882ee4febe\" style=\"color: rgb(0, 0, 0); font-size: 16px;\">Th&ecirc;́ mạnh</b></span></span></p>\r\n		</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">Minh Thành Group&nbsp;đã, đang, và sẽ ph&acirc;́n đ&acirc;́u trở thành c&ocirc;ng ty s&ocirc;́ m&ocirc;̣t trong ngành, chuy&ecirc;n cung c&acirc;́p các giải pháp quan trắc m&ocirc;i trường tự đ&ocirc;̣ng li&ecirc;n tục, với những th&ecirc;́ mạnh đang d&acirc;̀n được khẳng định v&ecirc;̀ cả c&ocirc;ng ngh&ecirc;̣, dịch vụ l&acirc;̃n con người, cụ th&ecirc;̉:</span></span></span></p>\r\n\r\n<ul>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">C&ocirc;ng ngh&ecirc;̣ UV-DOAS duy nh&acirc;́t tại Vi&ecirc;̣t Nam: Dựa tr&ecirc;n nguy&ecirc;n tắc đo sự h&acirc;́p thụ vi sao của tín hi&ecirc;̣u đ&ecirc;́n trong vùng bước sóng quan t&acirc;m sau khi nó đi qua m&ocirc;i trường khí, DOAS sử dụng ngu&ocirc;̀n sáng băng th&ocirc;ng r&ocirc;̣ng và phép đo được thực hi&ecirc;̣n tr&ecirc;n m&ocirc;̣i dải bước sóng lớn, cho phép đo chúng&nbsp;</span></span></span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">Lắp đặt thay th&ecirc;́ thi&ecirc;́t bị: MTG tự ti&ecirc;n là đơn vị ti&ecirc;n phong trong vi&ecirc;̣c lắp đặt, thay th&ecirc;́ sữa chữa các thi&ecirc;́t bị v&ecirc;̀ quan trắc m&ocirc;i trường tự đ&ocirc;̣ng, tạo đi&ecirc;̀u ki&ecirc;̣n h&ocirc;̃ trợ t&ocirc;́i đa cho doanh nghi&ecirc;̣p, là giải pháp an toàn, ti&ecirc;́t ki&ecirc;̣m t&ocirc;́i ưu nh&acirc;́t tr&ecirc;n thị trường</span></span></span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">TUV (Đức), và EPA (Hoa Kỳ): MTG t&acirc;̣p trung cung c&acirc;́p những sản ph&acirc;̉m với đặc tính an toàn, ch&acirc;́t lượng, đ&ocirc;̣ b&ecirc;̀n, đ&ocirc;̣ tương thích với m&ocirc;i trường và tu&acirc;n thủ các ti&ecirc;u chu&acirc;̉n hi&ecirc;̣n hành, được xác nh&acirc;̣n bởi Đức và Hoa Kỳ</span></span></span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">Gi&aacute;&nbsp;cả phải chăng: Với vi&ecirc;̣c t&ocirc;́i ưu hóa vi&ecirc;̣c tư v&acirc;́n, lắp đặt dựa tr&ecirc;n đặc đi&ecirc;̉m của từng doanh nghi&ecirc;̣p, MTG lu&ocirc;n đưa ra các giải pháp t&ocirc;́t nh&acirc;́t cho khách hàng, với ch&acirc;́t lượng dịch vụ, sản ph&acirc;̉m cao, nhưng với mức giá ti&ecirc;́t ki&ecirc;̣m nh&acirc;́t hi&ecirc;̣n tại</span></span></span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">Bảo hành 18-24 tháng: Chính sách h&ocirc;̃ trợ, bảo hành lu&ocirc;n được đi kèm khi MTG cung c&acirc;́p dịch vụ và lắp đặt cho doanh nghi&ecirc;̣p, đảm bảo h&ocirc;̃ trợ t&ocirc;́i đa 24/7 cho doanh nghi&ecirc;̣p khi gặp các v&acirc;́n đ&ecirc;̀ v&ecirc;̀ thi&ecirc;́t bị, v&acirc;̣n hành, &hellip;</span></span></span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\"><img alt=\"\" src=\"/storage/uploads/img-3.jpg\" style=\"width: 1200px; height: 730px;\" /></span></span></span></p>\r\n\r\n<p dir=\"ltr\"><span style=\"font-size:16px;\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"color:#000000;\"><strong>Hệ th&ocirc;́ng quan trắc tự đ&ocirc;̣ng do MTG cung c&acirc;́p, lu&ocirc;n:</strong></span></span></span></p>\r\n\r\n<ul>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">Đảm bảo phù hợp với th&ocirc;ng tư s&ocirc;́ 24/2017/TT &ndash; BTNMT và Nghị định s&ocirc;́ 40/2019/NĐ-CP</span></span></span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">Kiểm soát ch&acirc;́t lượng xả thải m&ocirc;i trường</span></span></span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">Dự đoán và phát hi&ecirc;̣n sự c&ocirc;́ trong quá trình sản xu&acirc;́t</span></span></span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">Kiểm soát v&acirc;̣n hành, bảo trì bảo dưỡng thi&ecirc;́t bị</span></span></span></p>\r\n	</li>\r\n	<li aria-level=\"1\" dir=\"ltr\">\r\n	<p dir=\"ltr\" role=\"presentation\"><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">Đ&aacute;nh giá hi&ecirc;̣u quả làm vi&ecirc;̣c của h&ecirc;̣ th&ocirc;́ng xử lý m&ocirc;i trường</span></span></span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\"><img alt=\"\" src=\"/storage/uploads/z2406664582853-6b38b556fa75737993d9227c6d738b0a.jpg\" style=\"width: 1200px; height: 900px;\" /></span></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\">C&aacute;c dự &aacute;n m&agrave; ch&uacute;ng t&ocirc;i đ&atilde; thực hiện trong suốt gần 04&nbsp;năm vừa qua</span></span></span></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\"><strong>C&ocirc;ng ty TNHH Vinatic</strong></span></span></span></li>\r\n	<li><span style=\"font-family:Tahoma,Geneva,sans-serif;\"><span style=\"font-size:14px;\"><span style=\"color:#000000;\"><strong